INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT159-S3-Q12$batch13$, 159, 3, 12, $batch13$Strengthen$batch13$, $batch13$When the annual period of daylight saving time begins, and clocks are set forward one hour, many people lose an hour of sleep. On the following day, according to government statistics, the incidence of traffic accidents is 7 percent greater than the average for that time of year. It is therefore likely that sleep deprivation is responsible for this spike in traffic accidents.$batch13$, $batch13$Which one of the following, if true, most strengthens the argument?$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Many people forget to set their clocks forward when daylight saving time begins and are late for appointments on the following day as a result.$batch13$, $batch13$Weakens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Traffic accidents are less common in the spring, when the annual period of daylight saving time begins, than they are in the winter.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$The traffic accidents that occur on the day after daylight saving time begins are no more severe than normal.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$The higher incidence of accidents is most pronounced later in the day, when sleep-deprived people tend to be most drowsy.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$The effects of sleep deprivation can linger for several days.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Sleep deprivation is probably responsible for the spike in traffic accidents on the day after clocks move forward.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Many people lose an hour of sleep when daylight saving time begins. The next day, accidents run 7 percent above average for that time of year.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The argument moves from a correlation to a cause. Other things change that day too. A strengthener could rule out another cause or show a detail that only sleep loss predicts.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Tie the extra accidents specifically to drowsiness.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$People late for appointments may rush. That's another possible cause of accidents.$batch13$), ($batch13$B$batch13$, $batch13$The comparison is already to the average for that time of year, so the seasonal difference doesn't matter.$batch13$), ($batch13$C$batch13$, $batch13$How severe the accidents are says nothing about their cause.$batch13$), ($batch13$D$batch13$, $batch13$The extra accidents cluster later in the day, when sleep-deprived people are drowsiest. Sleep loss predicts exactly that timing.$batch13$), ($batch13$E$batch13$, $batch13$If effects lingered for days, you'd expect the spike to last too. That doesn't help explain the one-day spike.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT159-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
